// Validates the PUBLIC health-search configuration (carrier identities,
// schedules, outcome rules, medical terms in server/health-search/data/)
// and writes server/health-search/config.generated.js, which the search API
// imports. Question records are never part of it: they live only in the
// private search store (scripts/health-search-publish.mjs).
//
//   npm run health-search:data            validate + generate
//   npm run health-search:data -- --check fail if the generated file is stale

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateDataset } from '../server/health-search/validate.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'server', 'health-search');
const read = (p) => JSON.parse(readFileSync(join(root, 'data', p), 'utf8'));
const carriers = read('carriers.json');
const concepts = read('concepts.json');

const result = validateDataset({ carriers, questionFiles: [], concepts }, { configOnly: true });
for (const w of result.warnings) console.warn(`warning: ${w}`);
if (result.errors.length) {
  for (const e of result.errors) console.error(`error: ${e}`);
  console.error(`\nhealth-search config: ${result.errors.length} error(s); config.generated.js not written.`);
  process.exit(1);
}

const strip = (o) => JSON.parse(JSON.stringify(o, (k, v) => (k.startsWith('_') ? undefined : v)));
const config = {
  expectedQuestionTotal: carriers.expectedQuestionTotal,
  carriers: strip(carriers.carriers),
  concepts: strip(concepts.concepts),
};
const out = `// GENERATED by scripts/health-search-data.mjs from server/health-search/data/.
// Do not edit by hand. Public configuration only: no question records.
export const config = ${JSON.stringify(config, null, 1)};
`;
const target = join(root, 'config.generated.js');
if (process.argv.includes('--check')) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== out) {
    console.error('health-search config: config.generated.js is out of date. Run `npm run health-search:data`.');
    process.exit(1);
  }
  console.log(`health-search config: up to date (${config.carriers.length} carriers, ${config.expectedQuestionTotal} questions expected).`);
} else {
  writeFileSync(target, out);
  console.log(`health-search config: wrote config.generated.js (${config.carriers.length} carriers, ${config.expectedQuestionTotal} questions expected; questions are published separately).`);
}
